/**
 * `agent-sdk docs` / `npx @grok/agent-sdk docs` — serve the shipped VitePress
 * site on loopback and open it in a browser. Does not start an agent host.
 */
import { once } from "node:events";
import { createServer } from "node:http";
import { tcpAddress } from "./tcp-address.js";
import { PACKAGE_NAME } from "./distribution.js";
import { docsSiteExists, ensureDocsSiteBundle, renderDocsFile } from "./docs-site.js";
import { openBrowser } from "./open-browser.js";
export async function cmdDocs(options = {}) {
    const stdout = options.stdoutWrite ?? ((c) => void process.stdout.write(c));
    const stderr = options.stderrWrite ?? ((c) => void process.stderr.write(c));
    await (options.ensureBundle ?? ensureDocsSiteBundle)();
    if (!(options.siteExists ?? docsSiteExists)()) {
        stderr(`Documentation site is missing from this install. Reinstall ${PACKAGE_NAME}, or from a source checkout run: pnpm run docs:build\n`);
        return 1;
    }
    let handle;
    try {
        handle = await startDocsServer({
            port: options.port ?? 0,
            host: options.host ?? "127.0.0.1",
            renderFile: options.renderFile ?? ((path) => renderDocsFile(path)),
            createServerImpl: options.createServerImpl ?? createServer,
        });
    }
    catch (error) {
        stderr(`${error instanceof Error ? error.message : String(error)}\n`);
        return 1;
    }
    stdout(`${handle.docsUrl}\n`);
    stderr("Docs on loopback (Ctrl-C to stop).\n");
    if (options.print !== true) {
        (options.openBrowserImpl ?? openBrowser)(handle.docsUrl);
    }
    const controller = new AbortController();
    const onSignal = () => {
        controller.abort();
    };
    process.on("SIGINT", onSignal);
    process.on("SIGTERM", onSignal);
    const external = options.signal;
    if (external !== undefined) {
        if (external.aborted) {
            controller.abort();
        }
        else {
            external.addEventListener("abort", onSignal, { once: true });
        }
    }
    try {
        await new Promise((resolve) => {
            if (controller.signal.aborted) {
                resolve();
                return;
            }
            controller.signal.addEventListener("abort", () => resolve(), {
                once: true,
            });
        });
        return 0;
    }
    finally {
        process.off("SIGINT", onSignal);
        process.off("SIGTERM", onSignal);
        external?.removeEventListener("abort", onSignal);
        await handle.close().catch(() => { });
    }
}
export async function startDocsServer(args) {
    const server = args.createServerImpl((req, res) => {
        void handleDocsRequest(req, res, args.renderFile);
    });
    try {
        server.listen(args.port, args.host);
        await once(server, "listening");
    }
    catch (error) {
        server.close();
        throw error;
    }
    const address = tcpAddress(server);
    const displayHost = args.host === "0.0.0.0" || args.host === "::" ? "127.0.0.1" : args.host;
    const url = `http://${displayHost}:${address.port}`;
    return {
        url,
        docsUrl: `${url}/docs/`,
        port: address.port,
        close: () => new Promise((resolve, reject) => {
            server.close((err) => (err !== undefined ? reject(err) : resolve()));
        }),
    };
}
async function handleDocsRequest(req, res, renderFile) {
    const method = req.method ?? "GET";
    if (method !== "GET" && method !== "HEAD") {
        res.writeHead(405, { allow: "GET, HEAD" });
        res.end();
        return;
    }
    const host = req.headers.host ?? "127.0.0.1";
    let pathname;
    try {
        pathname = new URL(req.url ?? "/", `http://${host}`).pathname;
    }
    catch {
        res.writeHead(400);
        res.end();
        return;
    }
    if (pathname === "/" || pathname === "") {
        res.writeHead(302, { location: "/docs/" });
        res.end();
        return;
    }
    if (pathname === "/v1/health" || pathname === "/v1/health/") {
        // Same path the corp ALB / ECS check uses on agent-serve. Static docs
        // has no runtimes; liveness is "the process accepted HTTP".
        res.writeHead(200, { "content-type": "application/json; charset=utf-8" });
        if (method === "HEAD") {
            res.end();
            return;
        }
        res.end(JSON.stringify({ ok: true }));
        return;
    }
    let requestPath;
    if (pathname === "/docs" || pathname === "/docs/") {
        requestPath = "";
    }
    else if (pathname.startsWith("/docs/")) {
        try {
            requestPath = decodeURIComponent(pathname.slice("/docs/".length));
        }
        catch {
            res.writeHead(400);
            res.end();
            return;
        }
    }
    else {
        res.writeHead(404, { "content-type": "text/plain; charset=utf-8" });
        res.end("Not found");
        return;
    }
    const response = renderFile(requestPath);
    res.writeHead(response.status, Object.fromEntries(response.headers));
    if (method === "HEAD" || response.body === null) {
        if (response.body !== null) {
            void response.body.cancel().catch(() => { });
        }
        res.end();
        return;
    }
    res.end(Buffer.from(await response.arrayBuffer()));
}
